import { revalidateTag, unstable_cache } from 'next/cache';

// Mock product data fetcher
const getCatalogData = unstable_cache(
  async () => {
    // Simulate slow upstream ERP/PIM API
    await new Promise((resolve) => setTimeout(resolve, 2000));
    const now = new Date().toISOString();
    return [
      { id: 'SKU-001', name: 'Wireless Headphones', price: 199.99, lastUpdated: now },
      { id: 'SKU-002', name: 'Ergonomic Keyboard', price: 149.99, lastUpdated: now },
      { id: 'SKU-003', name: '27" 4K Monitor', price: 399.99, lastUpdated: now },
      { id: 'SKU-004', name: 'USB-C Hub', price: 49.99, lastUpdated: now },
    ];
  },
  ['catalog-data-key'], // cache key
  {
    tags: ['products'], // cache tag for invalidation
  }
);

export default async function AdminCatalogPage() {
  const products = await getCatalogData();

  async function syncCatalog() {
    'use server';
    // Use stale-while-revalidate invalidation via profile "max".
    // This allows the admin to continue working immediately,
    // while the refresh happens in the background.
    revalidateTag('products', 'max');
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <h1>Admin Product Catalog</h1>
        <form action={syncCatalog}>
          <button 
            type="submit" 
            style={{ 
              padding: '0.5rem 1rem', 
              backgroundColor: '#0070f3', 
              color: 'white', 
              border: 'none', 
              borderRadius: '4px', 
              cursor: 'pointer' 
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </header>

      <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid #eaeaea' }}>
            <th style={{ padding: '0.5rem' }}>SKU</th>
            <th style={{ padding: '0.5rem' }}>Name</th>
            <th style={{ padding: '0.5rem' }}>Price</th>
            <th style={{ padding: '0.5rem' }}>Last Updated (ERP/PIM)</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #eaeaea' }}>
              <td style={{ padding: '0.5rem' }}>{product.id}</td>
              <td style={{ padding: '0.5rem' }}>{product.name}</td>
              <td style={{ padding: '0.5rem' }}>${product.price}</td>
              <td style={{ padding: '0.5rem', color: '#666' }}>{product.lastUpdated}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p style={{ marginTop: '2rem', fontSize: '0.875rem', color: '#666' }}>
        Note: The sync action processes thousands of SKUs in the background. It may take a moment for all views to reflect the updated data.
      </p>
    </div>
  );
}

